<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeAllowController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeListController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeCreateController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeRetrieveController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeUpdateController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeDeleteController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeEnableController;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest\ThemeDisableController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeCollectNonEditableFields;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Create\ThemeCreateAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Update\ThemeUpdateAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Retrieve\ThemeRetrieveAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\List\ThemeListAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Delete\ThemeDeleteAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Enable\IsAuthenticatedEnableAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Enable\ThemeEnableAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Disable\IsAuthenticatedDisableAllow;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Disable\ThemeDisableAllowDecision;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driven\ThemeReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Driven\ThemeWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeReadGateway;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;

class ThemePlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ThemeReadGateway::class] = \DI\autowire(ThemeReadRepositoryAdapter::class);
        $def[ThemeWriteGateway::class] = \DI\autowire(ThemeWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/theme', [$this, 'setRoutesForTheme']);
        $collector->group('/api/me/acl/document/theme', [$this, 'setRoutesForThemeAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(ThemeRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(ThemeCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $listener->registerListener(ThemeCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(ThemeUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(ThemeRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(ThemeListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(ThemeDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
        $listener->registerListener(ThemeEnableAllowDecision::class, IsAuthenticatedEnableAllow::class);
        $listener->registerListener(ThemeDisableAllowDecision::class, IsAuthenticatedDisableAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("theme", "list", "READ");
            $handler->registerResourceAction("theme", "create", "WRITE");
            $handler->registerResourceAction("theme", "retrieve", "READ");
            $handler->registerResourceAction("theme", "update", "WRITE");
            $handler->registerResourceAction("theme", "delete", "WRITE");
            $handler->registerResourceAction("theme", "enable", "WRITE");
            $handler->registerResourceAction("theme", "disable", "WRITE");

            $handler->registerResourceAttribute("theme", "tenant", "MANAGE");
            $handler->registerResourceAttribute("theme", "name", "MANAGE");
            $handler->registerResourceAttribute("theme", "isDefault", "MANAGE");
            $handler->registerResourceAttribute("theme", "enabled", "MANAGE");
            $handler->registerResourceAttribute("theme", "customCss", "MANAGE");
            $handler->registerResourceAttribute("theme", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForThemeAcl(RouteCollectorProxy $themeGroup): void
    {
        $themeGroup->get('', [ThemeAllowController::class, 'genericAllow']);
        $themeGroup->get('/{uid}', [ThemeAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForTheme(RouteCollectorProxy $themeGroup): void
    {
        $themeGroup->get('', [ThemeListController::class, 'list']);
        $themeGroup->post('', [ThemeCreateController::class, 'create']);
        $themeGroup->get('/{uid}', [ThemeRetrieveController::class, 'retrieve']);
        $themeGroup->put('/{uid}', [ThemeUpdateController::class, 'update']);
        $themeGroup->delete('/{uid}', [ThemeDeleteController::class, 'delete']);
        $themeGroup->delete('', [ThemeDeleteController::class, 'deleteAllForQuery']);
        $themeGroup->get('/~/delete-status/{uid}', [ThemeDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $themeGroup->patch('/~/enable', [ThemeEnableController::class, 'enableAllForQuery']);
        $themeGroup->patch('/{uid}/enable', [ThemeEnableController::class, 'enable']);
        $themeGroup->get('/~/enable-status/{uid}', [ThemeEnableController::class, 'checkEnableAllForQueryStatus']);
        $themeGroup->patch('/~/disable', [ThemeDisableController::class, 'disableAllForQuery']);
        $themeGroup->patch('/{uid}/disable', [ThemeDisableController::class, 'disable']);
        $themeGroup->get('/~/disable-status/{uid}', [ThemeDisableController::class, 'checkDisableAllForQueryStatus']);
    }
}
